    LPDrawingState storage currentLP = lpDrawingState[_drawingId];
    if (_lpPoolCap < currentLP.lpPoolTotal + currentLP.pendingDeposits) revert InvalidLPPoolCap();
    lpPoolCap = _lpPoolCap;
}

